// Browser-local prototype. None of these actions contact a verification, maps, or payment provider.
const storeKey='cr_demo_v2';let demo=JSON.parse(localStorage.getItem(storeKey)||'{"role":"student","drivers":[],"bookings":[]}');
function saveDemo(){localStorage.setItem(storeKey,JSON.stringify(demo))}function money(n){return '$'+Number(n).toFixed(2)}function newId(){return Date.now()+Math.floor(Math.random()*1000)}
const nav=document.querySelector('nav');nav.insertAdjacentHTML('beforeend','<button data-extra="driver">Offer a ride</button><button data-extra="safety">Safety</button>');
const main=document.querySelector('main');main.insertAdjacentHTML('beforeend',`<section id="driver" class="hidden"><div class="box extended"><div class="eyebrow">For student drivers</div><h2>Offer a ride</h2><p class="sub">Set your route, car details and price. Your ride will appear in Discover on this device.</p><div class="form-grid"><div class="field"><label>STARTING ADDRESS</label><input id="dFrom" placeholder="123 College Ave"></div><div class="field"><label>PICKUP CITY</label><input id="dCity" placeholder="Los Angeles"></div><div class="field"><label>PICKUP STATE</label><input id="dState" placeholder="CA" maxlength="2" value="CA"></div><div class="field"><label>PICKUP ZIP CODE</label><input id="dZip" inputmode="numeric" placeholder="90024" maxlength="10"></div><div class="field"><label>DESTINATION ADDRESS</label><input id="dTo" placeholder="456 Main St, San Diego, CA 92101"></div><div class="field"><label>DATE</label><input id="dDate" type="date"></div><div class="field"><label>TIME</label><input id="dTime" type="time"></div><div class="field"><label>CAR MAKE AND MODEL</label><input id="dCar" placeholder="Toyota RAV4"></div><div class="field"><label>CAR COLOR</label><input id="dColor" placeholder="Silver"></div><div class="field"><label>CAR PHOTO</label><input id="dPhoto" type="file" accept="image/*"></div><div class="field"><label>PASSENGER SEATS (MAXIMUM 4)</label><input id="dSeats" type="number" min="1" max="4" step="1" value="4"></div><div class="field"><label>LUGGAGE LIMIT</label><input id="dLuggage" placeholder="1 suitcase per person"></div><div class="field"><label>DROPOFF RADIUS (MILES)</label><input id="dRadius" type="number" min="1" max="30" value="10"></div><div class="field"><label>ESTIMATED ROUTE DISTANCE (MILES)</label><input id="dMiles" type="number" min="1" value="100"></div><div class="field"><label>YOUR PRICE PER STUDENT ($)</label><input id="dPrice" type="number" min="1" value="25"></div></div><p class="suggestion" id="suggestion"></p><p class="note">The suggestion is an estimate based on distance. You choose the price. Riders can propose another amount.</p><button class="primary" id="postRide">Post ride</button><p class="note" id="driverMessage"></p></div></section><section id="safety" class="hidden"><div class="box extended"><div class="eyebrow">Ride with confidence</div><h2>Share your ride</h2><p class="sub">After a driver accepts a request, you can prepare a ride update for someone you trust.</p><div id="safetyBookings" style="margin-top:20px"></div><div class="safety-note"><b>Location sharing</b><p>Live tracking requires a location service and a secure sharing link. This demo can share trip details, but does not transmit live location. Use your phone's location-sharing feature for live updates.</p></div></div></section>`);
const profile=$('profile');profile.innerHTML=`<div class="box extended"><div class="eyebrow">Your account</div><h2>Student signup</h2><p class="sub">Create a demo student profile and choose how you want to use RideLink.</p><div class="form-grid"><div class="field"><label>I WANT TO</label><select id="role"><option value="student">Find a ride</option><option value="driver">Drive students</option><option value="both">Both</option></select></div><div class="field"><label>FULL NAME</label><input id="profileName" placeholder="Your name"></div><div class="field"><label>STUDENT EMAIL</label><input id="email" type="email" placeholder="you@college.edu"></div><div class="field"><label>COLLEGE NAME</label><input id="college" placeholder="Your college"></div><div class="field"><label>YEAR IN COLLEGE</label><select id="year"><option>First year</option><option>Sophomore</option><option>Junior</option><option>Senior</option><option>Graduate student</option></select></div><div class="field"><label>GENDER (OPTIONAL)</label><input id="gender" placeholder="How you identify"></div><div class="field"><label>DRIVER PREFERENCE (OPTIONAL)</label><input id="preference" placeholder="Your preference"></div><div class="field"><label>PROFILE PHOTO</label><input id="profilePhoto" type="file" accept="image/*"><img id="photoPreview" alt="Your profile photo preview" class="preview hidden"></div></div><div class="verify-box"><b>Student verification</b><p>Enter your student email and try the demo verification flow. No email is sent and your student status is not actually checked.</p><button class="secondary" id="verifyDemo">Simulate verification</button> <span id="verifyStatus"></span></div><div class="verify-box"><b>Driver license verification</b><p>Drivers will need a secure license verification provider. Do not upload a license in this demo.</p><span class="tag">Not connected</span></div><button class="primary" id="saveProfile2">Save demo profile</button><p class="note" id="profileMessage"></p></div>`;
// Reset original tab listeners, which assumed only three screens.
for(const b of [...document.querySelectorAll('nav button')]){let n=b.cloneNode(true);b.replaceWith(n)}function go(tab){['discover','trips','profile','driver','safety'].forEach(x=>$(x).classList.toggle('hidden',x!==tab));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',(b.dataset.tab||b.dataset.extra)===tab));if(tab==='trips')renderTrips();if(tab==='safety')renderSafety()}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.tab||b.dataset.extra));
let profileData=JSON.parse(localStorage.getItem('cr_profile')||'{}');for(const [id,key] of Object.entries({profileName:'name',email:'email',college:'college',preference:'preference',year:'year',gender:'gender',role:'role'}))if(profileData[key])$(id).value=profileData[key];let profileImage=profileData.photo||'';if(profileImage){$('photoPreview').src=profileImage;$('photoPreview').classList.remove('hidden')}function readImage(input,cb){let f=input.files[0];if(!f)return;let url=URL.createObjectURL(f),img=new Image();img.onload=()=>{let canvas=document.createElement('canvas'),scale=Math.min(1,1200/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);cb(canvas.toDataURL('image/jpeg',0.75))};img.onerror=()=>{URL.revokeObjectURL(url);alert('Could not read this image. Please choose a different photo.')};img.src=url}$('profilePhoto').onchange=e=>readImage(e.target,v=>{profileImage=v;$('photoPreview').src=v;$('photoPreview').classList.remove('hidden')});$('verifyDemo').onclick=()=>{if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test($('email').value)){alert('Enter a valid student email first.');return}$('verifyStatus').textContent='Demo complete — not actually verified';};$('saveProfile2').onclick=()=>{let email=$('email').value.trim(),name=$('profileName').value.trim();if(!name||!email||!$('college').value.trim()){alert('Please enter your name, student email, and college.');return}profileData={name,email,college:$('college').value.trim(),year:$('year').value,gender:$('gender').value,preference:$('preference').value,role:$('role').value,photo:profileImage};try{localStorage.setItem('cr_profile',JSON.stringify(profileData));demo.role=profileData.role;saveDemo();$('profileMessage').textContent='Profile saved on this device. Student verification is not connected.'}catch(e){$('profileMessage').textContent='Could not save. Try a smaller photo.'}};
let carImage='';$('dPhoto').onchange=e=>readImage(e.target,v=>carImage=v);function suggested(){let n=Math.max(1,+$('dMiles').value||1);$('suggestion').textContent='Suggested price: '+money(Math.max(5,Math.round(n*.25)))+' per student';} $('dMiles').oninput=suggested;suggested();$('postRide').onclick=()=>{let street=$('dFrom').value.trim(),city=$('dCity').value.trim(),state=$('dState').value.trim(),zip=$('dZip').value.trim(),from=[street,city,state+' '+zip].join(', '),to=$('dTo').value.trim(),date=$('dDate').value,car=$('dCar').value.trim(),price=+$('dPrice').value,seats=+$('dSeats').value,rad=+$('dRadius').value;if(!profileData.name){$('driverMessage').textContent='Create your student profile first.';return}if(!street||!city||!/^[A-Za-z]{2}$/.test(state)||!/^\d{5}(-\d{4})?$/.test(zip)||!to||!date||!car||price<=0||rad<1||rad>30||!Number.isInteger(seats)||seats<1||seats>4){$('driverMessage').textContent='Enter pickup street, city, two-letter state and ZIP, destination, date, car, price, 1–4 seats, and a radius from 1 to 30 miles.';$('driverMessage').scrollIntoView({behavior:'smooth',block:'center'});return}let r={id:newId(),name:profileData.name,initials:profileData.name.split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase(),college:profileData.college+' · '+profileData.year,gender:profileData.gender||'Not specified',rating:'New',reviews:0,from,to,date,time:$('dTime').value||'Time TBD',seats,price,car:car+' · '+$('dColor').value,luggage:$('dLuggage').value||'Ask driver',radius:rad,photo:profileData.photo||'',carPhoto:carImage};demo.drivers.push(r);try{saveDemo();rides.push(r);$('driverMessage').textContent='Ride posted to this device.';render(rides);go('trips')}catch(e){demo.drivers.pop();$('driverMessage').textContent='Could not save. Try smaller photos.'}};demo.drivers.forEach(r=>rides.push(r));render(rides);
// The map is a schematic, not geocoded; the circle represents the selected distance.
const radiusField=$('radius').closest('.field');radiusField.insertAdjacentHTML('afterend',`<div class="map-demo" aria-label="Illustration of selected dropoff radius"><div class="map-street street-a"></div><div class="map-street street-b"></div><div class="map-street street-c"></div><div class="map-circle" id="mapCircle"></div><div class="map-pin">●</div><div class="map-label">Destination</div></div><p class="note map-caption">Illustration only · exact addresses and distances require maps integration</p>`);function mapRadius(){let v=+$('radius').value;$('radiusValue').textContent=v+' miles';$('mapCircle').style.width=(45+v*3)+'px';$('mapCircle').style.height=(45+v*3)+'px'}$('radius').oninput=mapRadius;mapRadius();$('from').placeholder='Pickup street address';$('from').value='';$('to').placeholder='Destination street address or city';$('to').previousElementSibling.textContent='DESTINATION ADDRESS';$('from').previousElementSibling.textContent='PICKUP ADDRESS';$('seats').insertAdjacentHTML('beforeend','<option value="4">4 students</option>');
// Replace request dialog with an explicit simulated booking and payment breakdown.
requestRide=function(id){let r=rides.find(x=>x.id===id),n=Math.min(+$('seats').value,r.seats);$('modalTitle').textContent='Ride with '+r.name;$('modalContent').innerHTML=`<p>${esc(r.from)} → ${esc(r.to)}<br>${esc(r.date)} at ${esc(r.time)} · ${r.seats} passenger seats available<br>${esc(r.car)} · ${esc(r.luggage)}<br>Driver accepts dropoffs within ${r.radius} miles.</p>${r.photo?`<img class="preview" alt="Driver photo" src="${r.photo}">`:''}${r.carPhoto?`<img class="preview" alt="Car photo" src="${r.carPhoto}">`:''}<div class="field"><label>GROUP SIZE</label><select id="group">${Array.from({length:r.seats},(_,i)=>`<option value="${i+1}" ${n===i+1?'selected':''}>${i+1} student${i?'s':''}</option>`).join('')}</select></div><div class="field"><label>YOUR OFFER PER STUDENT ($) · DRIVER PRICE ${money(r.price)}</label><input id="offer" type="number" min="1" step="0.01" value="${r.price}"></div><div class="field"><label>YOUR EXACT DROPOFF ADDRESS</label><input id="dropAddress" placeholder="Street address, city, state"></div><div class="field"><label>EXTRA MILES BEYOND AGREED DROPOFF</label><input id="extraMiles" type="number" min="0" step="0.1" value="0"></div><p class="note">Extra miles are illustrative at $3 per mile for the group and require driver agreement. Driver must accept your request.</p><div class="payment-breakdown" id="total"></div><p class="note">Demo payment only: no card is charged, money is held, or funds transferred.</p><div class="actions"><button class="primary" id="sendRequest">Send request</button><button class="secondary" onclick="closeModal()">Close</button></div>`;$('modal').classList.add('open');function total(){let base=(+$('offer').value||0)*(+$('group').value),extra=(+$('extraMiles').value||0)*3,fee=(base+extra)*.08;$('total').innerHTML=`Ride: ${money(base)} · Extra distance: ${money(extra)}<br>Service fee (8%): ${money(fee)}<br><b>Demo total: ${money(base+extra+fee)}</b>`}['offer','group','extraMiles'].forEach(x=>$(x).oninput=total);total();$('sendRequest').onclick=()=>{let offer=+$('offer').value,group=+$('group').value,extra=+$('extraMiles').value,drop=$('dropAddress').value.trim();if(offer<=0||extra<0||!drop){alert('Enter a positive offer, a valid distance, and a dropoff address.');return}let subtotal=offer*group+extra*3;requests.push({id:newId(),ride:r.name,rideId:r.id,route:r.from+' → '+r.to,date:r.date,group,offer,drop,extra,total:Math.round(subtotal*1.08*100)/100,status:'Pending driver acceptance'});localStorage.setItem('cr_requests',JSON.stringify(requests));cardIndex++;showCard();$('modalContent').innerHTML='<p>Request saved. This is a demo, so the driver has not received it. Use My trips to simulate acceptance and payment.</p><button class="primary" onclick="closeModal()">Got it</button>'}};
function renderTrips(){let el=$('tripList');$('trips').querySelector('.sub').textContent='Demo requests are saved on this device. Cancellation policy: cancel at least 24 hours before departure; exceptions and refunds require review in a real service.';if(!requests.length){el.innerHTML='<p class="sub">No requests yet. Find a ride to get started.</p>';return}el.innerHTML=requests.map(x=>`<div class="trip-row"><b>${esc(x.route)}</b><p class="sub">${esc(x.ride)} · ${esc(x.date)} · ${x.group} seat(s) · Offer ${money(x.offer)} each</p><p class="sub">Dropoff: ${esc(x.drop||'Not provided')} · Demo total: ${money(x.total||x.offer*x.group*1.08)}</p><span class="tag">${esc(x.status)}</span><div class="actions">${x.status==='Pending driver acceptance'?`<button class="secondary" onclick="demoAccept(${x.id})">Simulate driver acceptance</button>`:''}${x.status==='Accepted · payment not simulated'?`<button class="primary" onclick="demoPay(${x.id})">Simulate payment hold</button>`:''}${x.status==='Booked · simulated hold'?`<button class="secondary" onclick="demoComplete(${x.id})">Simulate ride completion</button><button class="secondary" onclick="demoOutcome(${x.id})">Refund or partial trip</button><button class="secondary" onclick="demoCode(${x.id})">Pickup code</button><button class="secondary" onclick="go('safety')">Share ride</button>`:''}<button class="secondary" onclick="cancel(${x.id});renderTrips()">Remove demo request</button></div></div>`).join('')}
function updateRequest(id,status){let x=requests.find(r=>r.id===id);if(!x)return;x.status=status;localStorage.setItem('cr_requests',JSON.stringify(requests));renderTrips()}function demoAccept(id){updateRequest(id,'Accepted · payment not simulated')}function demoPay(id){updateRequest(id,'Booked · simulated hold')}function demoComplete(id){updateRequest(id,'Completed · simulated payout')}function demoCode(id){let x=requests.find(r=>r.id===id);if(!x.code){x.code=String(Math.floor(100000+Math.random()*900000));localStorage.setItem('cr_requests',JSON.stringify(requests))}alert('Demo pickup code: '+x.code+'. Show it to your driver at pickup. Real one-time verification is not connected.')}function demoOutcome(id){let outcome=prompt('Type REFUND for a simulated full refund or PARTIAL for a simulated 50% driver payout.');if(outcome==='REFUND')updateRequest(id,'Cancelled · simulated full refund');else if(outcome==='PARTIAL')updateRequest(id,'Partial trip · simulated 50% payout');}
function renderSafety(){let booked=requests.filter(x=>x.status==='Booked · simulated hold'||x.status==='Completed · simulated payout');$('safetyBookings').innerHTML=booked.length?booked.map(x=>`<div class="trip-row"><b>${esc(x.route)}</b><p class="sub">${esc(x.date)} · Driver ${esc(x.ride)} · ${esc(x.drop||'Dropoff not specified')}</p><button class="secondary" onclick="shareTrip(${x.id})">Share trip details</button></div>`).join(''):'<p class="sub">No booked rides yet. Simulate driver acceptance and a payment hold in My trips to try sharing.</p>'}async function shareTrip(id){let x=requests.find(r=>r.id===id),text=`My RideLink trip: ${x.route}, ${x.date}. Driver: ${x.ride}. Dropoff: ${x.drop||'not provided'}. This demo does not share live location.`;if(navigator.share){try{await navigator.share({title:'My ride details',text})}catch(e){}}else if(navigator.clipboard){try{await navigator.clipboard.writeText(text);alert('Trip details copied. You can send them to someone you trust.')}catch(e){prompt('Copy your trip details:',text)}}else prompt('Copy your trip details:',text)}
